mapper.select:
select T.*,T2.INSITITUTE_CODE insitituteCode from MST_BANK_NETVALUE T
LEFT JOIN MST_CUSTOMER_INFO_ADD T2 ON
T.CUSTOMER_ID=T2.CUSTOMER_ID


		and T.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}


		AND T.EFF_DATE = TO_DATE(#{effDate},'yyyy-MM-dd')


		and T.VAL_STATUS = #{valStatus,jdbcType=VARCHAR}


		and T.SEQNO = #{seqno,jdbcType=DECIMAL}


		and T2.INSITITUTE_CODE = #{insitituteCode,jdbcType=VARCHAR}

		SELECT max(T1.EFF_DATE) effDate
  			FROM MST_BANK_NETVALUE T1
  			LEFT JOIN MST_CUSTOMER_INFO_ADD T2 ON
		    T1.CUSTOMER_ID=T2.CUSTOMER_ID


				and T1.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}


				and VAL_STATUS = #{valStatus,jdbcType=VARCHAR}


				and SEQNO = #{seqno,jdbcType=DECIMAL}


				and T2.INSITITUTE_CODE = #{insitituteCode,jdbcType=VARCHAR}

mapper.update:
		update MST_BANK_NETVALUE


                NET_VALUE = #{netValue,jdbcType=DECIMAL},


                STATUS = #{statusLast,jdbcType=VARCHAR},


                REMARK = #{remark,jdbcType=VARCHAR},


                UPDATE_USER = #{updateUser,jdbcType=VARCHAR},


                UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP},


        where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
          and EFF_DATE = #{effDate,jdbcType=DATE}
          and STATUS = #{status,jdbcType=VARCHAR}
